import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in), 1 << 16);
        StringTokenizer st = new StringTokenizer("");
        List<String> tokens = new ArrayList<>();
        String line;
        while ((line = br.readLine()) != null) {
            st = new StringTokenizer(line);
            while (st.hasMoreTokens()) tokens.add(st.nextToken());
        }
        int n = Integer.parseInt(tokens.get(0));
        // Per activity level: {min heart rate, max heart rate}.
        HashMap<String, int[]> groups = new HashMap<>();
        for (int i = 0; i < n; i++) {
            int v = Integer.parseInt(tokens.get(1 + 2 * i));
            String c = tokens.get(2 + 2 * i);
            int[] g = groups.get(c);
            if (g == null) groups.put(c, new int[] {v, v});
            else {
                g[0] = Math.min(g[0], v);
                g[1] = Math.max(g[1], v);
            }
        }
        int answer = 0;
        for (int[] g : groups.values()) answer = Math.max(answer, g[1] - g[0]);
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	next := func() string { sc.Scan(); return sc.Text() }
	n, _ := strconv.Atoi(next())
	// Per activity level: [min heart rate, max heart rate].
	groups := map[string][2]int{}
	for i := 0; i < n; i++ {
		v, _ := strconv.Atoi(next())
		c := next()
		if g, ok := groups[c]; ok {
			groups[c] = [2]int{min(g[0], v), max(g[1], v)}
		} else {
			groups[c] = [2]int{v, v}
		}
	}
	answer := 0
	for _, g := range groups {
		answer = max(answer, g[1]-g[0])
	}
	fmt.Println(answer)
}
